  busy=true;unseen.setEnabled(false);search.setAlpha(.5f);more.setEnabled(false);alternative.setEnabled(false);status.setText("Ищем по теме и проверяем тип, описание и ограничения…");
  new Thread(()->{JSONArray found=null;String error=null;JSONObject proposal=null;boolean cached=false;try{
   String key=cacheKey(query,mode);long age=System.currentTimeMillis()-prefs.getLong(key+"_at",0);
   if(!extend&&query.equals(prefs.getString(key+"_query",""))&&age>=0&&age<86400000){JSONObject stored=new JSONObject(prefs.getString(key,"{}"));found=stored.getJSONArray("movies");proposal=stored;cached=true;}
   else{JSONObject body=new JSONObject().put("query",query).put("type_override",mode).put("exclude_titles",excludes).put("research",extend);proposal=ApiClient.request(this,"ai/movies",body);if(alive&&token==generation)found=MovieClient.enrich(this,proposal,query,mode,()->alive&&token==generation);
    if(!extend&&found!=null&&history.visible(found,hideSeen()).length()<3&&alive&&token==generation){final JSONArray first=found;handler.post(()->{if(alive&&token==generation)status.setText("Совпадений пока мало — расширяем поиск в интернете…");});JSONArray prior=new JSONArray();for(int i=0;i<first.length();i++)prior.put(first.getJSONObject(i).optString("original_title"));try{JSONObject extra=ApiClient.request(this,"ai/movies",new JSONObject().put("query",query).put("type_override",mode).put("exclude_titles",prior).put("research",true));found=merge(first,MovieClient.enrich(this,extra,query,mode,()->alive&&token==generation));}catch(Exception retryError){if(first.length()==0)throw retryError;found=first;}}
   }
   if(found!=null&&alive&&token==generation){found=merge(existing,found);if(!cached){android.content.SharedPreferences.Editor e=prefs.edit();for(String old:prefs.getAll().keySet())if(old.startsWith("movie_cache_"))e.remove(old);JSONObject stored=new JSONObject().put("movies",found).put("requested_type",proposal.optString("requested_type","any")).put("allow_type_alternative",proposal.optBoolean("allow_type_alternative",false));e.putString(key,stored.toString()).putString(key+"_query",query).putLong(key+"_at",System.currentTimeMillis()).apply();}}
  }catch(Exception e){error=ApiClient.message(e);}final JSONArray result=found;final JSONObject meta=proposal;final String message=error;handler.post(()->{if(!alive||token!=generation)return;busy=false;unseen.setEnabled(true);search.setAlpha(1);more.setEnabled(true);alternative.setEnabled(true);if(message!=null){if(galleryNext!=null){galleryNext.setEnabled(pool.length()<48);galleryNext.setText("Повторить поиск");}status.setText(message);if(gallery!=null)Toast.makeText(this,message,1).show();return;}int previous=existing.length();pool=result==null?new JSONArray():result;currentQuery=query;kind=meta==null?"any":meta.optString("requested_type","any");allowAlternative=meta!=null&&meta.optBoolean("allow_type_alternative",false);render();if(extend&&pool.length()==previous)Toast.makeText(this,"Новых подтверждённых вариантов пока не найдено",1).show();if(gallery!=null)showGallery();});},"movie-picker").start();
