 static JSONArray merge(JSONArray first,JSONArray second){JSONArray out=new JSONArray();HashSet<Integer> seen=new HashSet<>();for(JSONArray a:new JSONArray[]{first,second})for(int i=0;i<a.length()&&out.length()<48;i++){JSONObject m=a.optJSONObject(i);if(m!=null&&seen.add(m.optInt("id")))out.put(m);}return out;}
