 void loadPoster(ImageView view,String path,int token){if(path.isEmpty())return;Bitmap cached=posterCache.get(path);if(cached!=null){view.setImageBitmap(cached);return;}posters.execute(()->{if(!alive||token!=imageEpoch)return;Bitmap image=null;try{image=MovieClient.poster(this,path);}catch(Exception ignored){}final Bitmap ready=image;handler.post(()->{if(ready==null)return;if(alive&&token==imageEpoch){posterCache.put(path,ready);view.setImageBitmap(ready);}else ready.recycle();});});}
 void details(JSONObject movie){String title=movie.optString("title");new LauncherDialogs.Builder(this).setTitle(title).setMessage(movie.optString("year")+" · "+movie.optInt("runtime")+" мин · ★ "+String.format(Locale.US,"%.1f",movie.optDouble("rating"))+"\n\n"+movie.optString("reason")).setPositiveButton("Где смотреть",(d,n)->availability(movie)).setNeutralButton(history.seen(movie.optInt("id"))?"Не смотрел":"Смотрел",(d,n)->mark(movie)).setNegativeButton("Назад",null).show();}
