  for(int i=0;i<tiles.size();i++){View tile=tiles.get(i);tile.setNextFocusLeftId(i%3>0?tiles.get(i-1).getId():tile.getId());tile.setNextFocusRightId(i%3<2&&i+1<tiles.size()?tiles.get(i+1).getId():tile.getId());tile.setNextFocusUpId(i>=3?tiles.get(i-3).getId():tile.getId());tile.setNextFocusDownId(i+3<tiles.size()?tiles.get(i+3).getId():next.isEnabled()?next.getId():close.getId());}next.setNextFocusRightId(close.getId());close.setNextFocusLeftId(next.isEnabled()?next.getId():close.getId());if(!tiles.isEmpty()){next.setNextFocusUpId(tiles.get(tiles.size()-1).getId());close.setNextFocusUpId(tiles.get(tiles.size()-1).getId());}
