 void cancelSearch(){generation++;busy=false;unseen.setEnabled(true);search.setAlpha(1);more.setEnabled(true);alternative.setEnabled(true);status.setText("Поиск остановлен");}
 String installedCinema(int index){String expected=PACKAGES[index];if(!expected.isEmpty()&&(getPackageManager().getLeanbackLaunchIntentForPackage(expected)!=null||getPackageManager().getLaunchIntentForPackage(expected)!=null))return expected;
  for(ResolveInfo info:getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER),0)){String label=info.loadLabel(getPackageManager()).toString().toLowerCase(new Locale("ru"));String wanted=CINEMAS[index].toLowerCase(new Locale("ru"));if(label.equals(wanted)||(index==3&&label.contains("premier"))||(index==6&&label.contains("kion")))return info.activityInfo.packageName;}return null;}
 void openCinema(String title){ArrayList<String> labels=new ArrayList<>(),packages=new ArrayList<>();for(int i=0;i<CINEMAS.length;i++)if(prefs.getBoolean("cinema_"+i,true)){String pkg=installedCinema(i);if(pkg!=null){labels.add(CINEMAS[i]);packages.add(pkg);}}
  if(labels.isEmpty()){Toast.makeText(this,"Выбранные кинотеатры не установлены",Toast.LENGTH_LONG).show();return;}
  new LauncherDialogs.Builder(this).setTitle("Открыть приложение для ручного поиска").setItems(labels.toArray(new String[0]),(d,n)->{Intent intent=getPackageManager().getLeanbackLaunchIntentForPackage(packages.get(n));if(intent==null)intent=getPackageManager().getLaunchIntentForPackage(packages.get(n));try{if(intent!=null)startActivity(intent);else throw new ActivityNotFoundException();}catch(Exception e){Toast.makeText(this,"Не удалось открыть приложение",0).show();}}).setNegativeButton("Отмена",null).show();
 }
 void availability(JSONObject movie){final int ticket=++availabilityGeneration;availabilityLoading=new LauncherDialogs.Builder(this).setTitle("Где смотреть · Россия").setMessage("Проверяем каталог TMDB / JustWatch…").setNegativeButton("Отмена",(d,n)->availabilityGeneration++).create();availabilityLoading.setOnCancelListener(d->availabilityGeneration++);availabilityLoading.show();new Thread(()->{JSONArray result=null;String error=null;try{JSONObject response=ApiClient.request(this,"tmdb/movie/"+movie.getInt("id")+"/watch/providers",null);result=MovieAvailability.offers(response);}catch(Exception e){error=ApiClient.message(e);}final JSONArray rows=result;final String failure=error;handler.post(()->{if(!alive||ticket!=availabilityGeneration)return;if(availabilityLoading!=null){availabilityLoading.dismiss();availabilityLoading=null;}AlertDialog.Builder b=new LauncherDialogs.Builder(this).setTitle("Где смотреть · Россия · JustWatch").setNegativeButton("Закрыть",null).setNeutralButton("Источник",(d,n)->availabilitySource(movie));if(failure!=null||rows==null||rows.length()==0){b.setMessage(failure!=null?"Проверка каталога недоступна. Наличие фильма не подтверждено.":"В справочнике нет предложений для России. Это не доказывает отсутствие фильма в кинотеатрах.").setPositiveButton("Ручной поиск",(d,n)->openCinema(movie.optString("title")));}else{String[] labels=new String[rows.length()];for(int i=0;i<labels.length;i++){JSONObject row=rows.optJSONObject(i);labels[i]=row.optString("name")+" · "+row.optString("offer");}b.setItems(labels,(d,n)->providerChoice(movie,rows.optJSONObject(n)));}b.show();});},"movie-availability").start();}
 void availabilitySource(JSONObject movie){try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.themoviedb.org/movie/"+movie.optInt("id")+"/watch?locale=RU")));}catch(Exception e){Toast.makeText(this,"На ТВ нет приложения для открытия страницы",1).show();}}
 void providerChoice(JSONObject movie,JSONObject provider){int index=MovieAvailability.cinema(provider.optString("name"));String pkg=index<0?null:installedCinema(index);AlertDialog.Builder b=new LauncherDialogs.Builder(this).setTitle(provider.optString("name")+" · "+provider.optString("offer")).setMessage("Источник: TMDB / JustWatch, Россия. Данные могут запаздывать; доступ по вашей подписке не проверен.\n\nПрямой переход к этому фильму в приложении пока не подтверждён. Можно открыть страницу доступности или приложение для ручного поиска.").setNeutralButton("Источник",(d,n)->availabilitySource(movie)).setNegativeButton("Назад",null);if(pkg!=null)b.setPositiveButton("Приложение",(d,n)->{try{Intent intent=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(intent==null)intent=getPackageManager().getLaunchIntentForPackage(pkg);if(intent!=null)startActivity(intent);}catch(Exception e){Toast.makeText(this,"Приложение недоступно",1).show();}});b.show();}
 public void onBackPressed(){if(listening){super.onBackPressed();return;}if(busy){cancelSearch();return;}super.onBackPressed();}
 protected void onPause(){availabilityGeneration++;if(availabilityLoading!=null){availabilityLoading.dismiss();availabilityLoading=null;}imageEpoch++;posters.getQueue().clear();if(busy)cancelSearch();super.onPause();}
 protected void onDestroy(){generation++;imageEpoch++;posters.shutdownNow();if(gallery!=null){gallery.setOnDismissListener(null);gallery.dismiss();gallery=null;}posterCache.evictAll();super.onDestroy();}
